import { defineHook } from '@directus/extensions-sdk';
import OpenAI from 'openai';

const openai = new OpenAI({ apiKey: process.env.OPENAI_API_KEY });

export default defineHook(({ action }) => {
  action('knowledge_base.items.create', async (meta, { database }) => {
    try {
      const item = await database('knowledge_base').where('id', meta.key).first();
      if (!item || !item.content) return;
      const res = await openai.embeddings.create({
        model: 'text-embedding-3-small',
        input: `${item.title}\n\n${item.content}`
      });
      await database('knowledge_base').where('id', meta.key).update({
        embedding: JSON.stringify(res.data[0].embedding)
      });
    } catch (e) {
      console.error('[RAG] Vectorization error:', e.message);
    }
  });
});
